-- migration_v49_humanizer_bank_soal.sql (antrean #257, 18 Okt 2026)
-- Permintaan Johan: "pastikan bank soal ini dan lain-lain gunakan /humanizer:humanizer". Tujuh agen sonnet menyunting
-- Bank Soal per bab menurut daftar pola §CORE-221; 9 soal berubah (teks pertanyaan, opsi, atau pembahasan).
-- Kunci jawaban, urutan opsi, dan level TIDAK berubah. Soal diperbarui di tempat (id tetap), jadi riwayat pengerjaan
-- mahasiswa tetap utuh. Satu transaksi: bila satu soal tidak ditemukan tepat satu, semuanya batal. Aman dijalankan ulang:
-- soal dicari dengan teks lama ATAU baru, jadi menjalankan lagi hanya menulis nilai yang sama.

DO $$
DECLARE k INT;
BEGIN
  -- Bab 1 Tes Diagnostik Awal no 8
  UPDATE quiz_questions q SET question = 'Catatan pengamatan di perpustakaan pascasarjana memuat tiga kalimat (angka rekaan). (1) Layanan perpustakaan ini kurang memuaskan. (2) Selama dua jam pengamatan, 14 dari 30 pengunjung menunggu lebih dari 10 menit di meja pengembalian. (3) Petugasnya tampak kurang peduli pada pengunjung. Kalimat mana yang paling layak dipakai di kolom masalah AM-1, dan mengapa?',
         options = '["Kalimat (1), karena merangkum keadaan layanan secara umum dalam satu kalimat ringkas", "Kalimat (3), karena menunjukkan penyebab utama antrean yang dialami para pengunjung itu", "Kalimat (2), karena menggambarkan kondisi yang dapat diamati dan diperiksa ulang orang lain", "Kalimat (1) dan (3), karena keduanya menggambarkan pengalaman pengunjung secara jujur"]'::JSONB,
         explanation = '[C4] Kolom masalah AM-1 meminta kondisi yang bisa diamati, bukan opini. Kalimat (3) tampak menjelaskan sebab, tetapi "kurang peduli" adalah kesan pengamat yang belum didukung catatan perilaku.'
    FROM courses c JOIN modules m ON m.course_id = c.id AND m.order_num = 1
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND q.kind = 'pre' AND q.course_id = c.id AND q.topik_id = m.id AND q.question IN ('Catatan pengamatan di perpustakaan pascasarjana memuat tiga kalimat (angka rekaan). (1) Layanan perpustakaan ini kurang memuaskan. (2) Selama dua jam pengamatan, 14 dari 30 pengunjung menunggu lebih dari 10 menit di meja pengembalian. (3) Petugasnya tampak kurang peduli pada pengunjung. Kalimat mana yang paling layak dipakai di kolom masalah AM-1, dan mengapa?', 'Catatan pengamatan di perpustakaan pascasarjana memuat tiga kalimat (angka rekaan). (1) Layanan perpustakaan ini kurang memuaskan. (2) Selama dua jam pengamatan, 14 dari 30 pengunjung menunggu lebih dari 10 menit di meja pengembalian. (3) Petugasnya tampak kurang peduli pada pengunjung. Kalimat mana yang paling layak dipakai di kolom masalah AM-1, dan mengapa?') AND q.answer_idx = 2;
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION 'Bab 1 pre no 8: % baris cocok (harus 1). Tidak ada yang diubah.', k; END IF;
  -- Bab 4 Tes Formatif no 13
  UPDATE quiz_questions q SET question = 'Mahasiswa akan mengembangkan pojok baca digital di perpustakaan desa (rekaan). Sejauh ini ia mengambil artikel dari halaman pertama mesin pencari, lalu menyesuaikan argumennya dengan apa yang kebetulan ditemukan. Rancangan langkah penelusuran yang paling tepat untuk ia susun adalah ...',
         options = '["Baca artikel di halaman pertama hasil pencarian dengan teliti, lalu pilih sumber yang paling mendukung argumen", "Kumpulkan sebanyak mungkin sumber dari berbagai mesin pencari, lalu tetapkan kriteria setelah draf rampung", "Batasi pencarian pada satu jurnal Scopus ternama agar sumbernya kredibel tanpa perlu banyak penyaringan", "Tetapkan kata kunci dan kriteria, cari luas di Google Scholar dan Garuda, saring, lalu dalami sisanya"]'::JSONB,
         explanation = '[C6] Penelusuran yang direncanakan dimulai dari kata kunci dan kriteria, lalu bergerak dari pencarian luas ke penyaringan dan pendalaman. Membatasi pada satu jurnal memang menjamin kredibilitas, tetapi membuang penelitian relevan di jurnal lain.'
    FROM courses c JOIN modules m ON m.course_id = c.id AND m.order_num = 4
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND q.kind = 'formatif' AND q.module_id = m.id AND q.question IN ('Mahasiswa akan mengembangkan pojok baca digital di perpustakaan desa (rekaan). Sejauh ini ia mengambil artikel dari halaman pertama mesin pencari, lalu menyesuaikan argumennya dengan apa yang kebetulan ditemukan. Rancangan langkah penelusuran yang paling tepat untuk ia susun adalah ...', 'Mahasiswa akan mengembangkan pojok baca digital di perpustakaan desa (rekaan). Sejauh ini ia mengambil artikel dari halaman pertama mesin pencari, lalu menyesuaikan argumennya dengan apa yang kebetulan ditemukan. Rancangan langkah penelusuran yang paling tepat untuk ia susun adalah ...') AND q.answer_idx = 3;
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION 'Bab 4 formatif no 13: % baris cocok (harus 1). Tidak ada yang diubah.', k; END IF;
  -- Bab 4 Tes Diagnostik Awal no 8
  UPDATE quiz_questions q SET question = 'Proposal aplikasi peminjaman loker di perpustakaan kampus rekaan memuat lima sumber: tiga buku tentang desain layanan dan sistem informasi, serta dua artikel jurnal tentang sistem peminjaman fasilitas di perpustakaan lain. Bagian yang paling perlu dilengkapi dalam kajian pustaka itu adalah ...',
         options = '["Penelitian sejenis, karena dua artikel jurnal belum cukup untuk dibandingkan dengan proyek", "Data atau kebijakan pendukung, misalnya aturan layanan loker dan data jumlah pemakainya", "Teori dasar, karena buku tentang desain layanan biasanya belum memuat temuan riset terbaru", "Kutipan langsung dari pakar, karena kajian pustaka itu belum memuat definisi baku tentang loker"]'::JSONB,
         explanation = '[C4] Kajian pustaka penelitian pengembangan idealnya memuat teori dasar, penelitian sejenis, dan data atau kebijakan pendukung. Buku dan artikel sudah mengisi dua jenis pertama, sehingga yang belum ada adalah data dan kebijakan dari lokasi proyek.'
    FROM courses c JOIN modules m ON m.course_id = c.id AND m.order_num = 4
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND q.kind = 'pre' AND q.course_id = c.id AND q.topik_id = m.id AND q.question IN ('Proposal aplikasi peminjaman loker di perpustakaan kampus rekaan memuat lima sumber: tiga buku tentang desain layanan dan sistem informasi, serta dua artikel jurnal tentang sistem peminjaman fasilitas di perpustakaan lain. Bagian yang paling perlu dilengkapi dalam kajian pustaka itu adalah ...', 'Proposal aplikasi peminjaman loker di perpustakaan kampus rekaan memuat lima sumber: tiga buku tentang desain layanan dan sistem informasi, serta dua artikel jurnal tentang sistem peminjaman fasilitas di perpustakaan lain. Bagian yang paling perlu dilengkapi dalam kajian pustaka itu adalah ...') AND q.answer_idx = 1;
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION 'Bab 4 pre no 8: % baris cocok (harus 1). Tidak ada yang diubah.', k; END IF;
  -- Bab 5 Tes Formatif no 8
  UPDATE quiz_questions q SET question = 'Untuk memilih ADDIE bagi e-modul literasi informasi, mahasiswa mengumpulkan dua bukti: (1) satu penelitian e-modul kimia SMK dengan skor validasi 92% dan nilai siswa naik dari 60 ke 85; (2) meta-analisis 23 artikel tentang ADDIE di pendidikan jarak jauh. Pernyataan mana yang paling tepat tentang kedua bukti itu?',
         options = '["Bukti pertama lebih kuat karena memuat angka validasi dan nilai tes, sedangkan meta-analisis lebih banyak merangkum pendapat", "Bukti kedua menggabungkan puluhan artikel, sedangkan bukti pertama hanya menunjukkan ADDIE berhasil di satu tempat", "Bukti pertama membuktikan bahwa ADDIE adalah penyebab naiknya nilai, sehingga bukti kedua tidak lagi diperlukan", "Kedua bukti sama kuatnya karena sama-sama memakai ADDIE, sehingga cukup dipilih salah satu saja untuk proposal"]'::JSONB,
         explanation = '[C4] Meta-analisis menggabungkan hasil puluhan artikel, sedangkan satu penelitian hanya menunjukkan keberhasilan di satu tempat dan belum tentu karena modelnya. Angka yang tinggi tidak dengan sendirinya membuktikan sebab.'
    FROM courses c JOIN modules m ON m.course_id = c.id AND m.order_num = 5
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND q.kind = 'formatif' AND q.module_id = m.id AND q.question IN ('Untuk memilih ADDIE bagi e-modul literasi informasi, mahasiswa mengumpulkan dua bukti: (1) satu penelitian e-modul kimia SMK dengan skor validasi 92% dan nilai siswa naik dari 60 ke 85; (2) meta-analisis 23 artikel tentang ADDIE di pendidikan jarak jauh. Pernyataan mana yang paling tepat tentang kedua bukti itu?', 'Untuk memilih ADDIE bagi e-modul literasi informasi, mahasiswa mengumpulkan dua bukti: (1) satu penelitian e-modul kimia SMK dengan skor validasi 92% dan nilai siswa naik dari 60 ke 85; (2) meta-analisis 23 artikel tentang ADDIE di pendidikan jarak jauh. Pernyataan mana yang paling tepat tentang kedua bukti itu?') AND q.answer_idx = 1;
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION 'Bab 5 formatif no 8: % baris cocok (harus 1). Tidak ada yang diubah.', k; END IF;
  -- Bab 5 Tes Formatif no 19
  UPDATE quiz_questions q SET question = 'Proyek tim: sistem informasi peminjaman ruang diskusi di perpustakaan kampus. Fitur sudah disepakati dengan kepala layanan, waktunya satu semester, dan tim belum pernah membangun sistem. Paragraf alasan pemilihan model mana yang paling tepat untuk proposal?',
         options = '["Kami memilih RAD karena model ini paling cepat. Situs web Delima dkk. (2017) selesai dalam 30 minggu, sehingga sistem ruang diskusi kami juga kemungkinan besar selesai lebih cepat dari jadwal semester.", "Kami memilih ADDIE karena model ini paling terkenal dan paling banyak dipakai. Banyak tim sudah memakainya, sehingga tidak perlu alasan lain.", "Kami memilih XP karena metode agile adalah yang terbaru. Kebutuhan sistem kami akan kami gali sambil berjalan bersama kepala layanan setiap hari.", "Kami memilih Waterfall karena kebutuhan sudah disepakati dan tahapnya jelas bagi tim pemula. Hasibuan dkk. (2026) memakainya untuk sistem sekolah; skor SUS mereka menjadi pembanding."]'::JSONB,
         explanation = '[C6] Alasan yang baik mengaitkan model dengan ciri proyek lalu menambahkan penelitian serupa sebagai pembanding. Paragraf RAD keliru karena mengubah hasil satu penelitian menjadi jaminan.'
    FROM courses c JOIN modules m ON m.course_id = c.id AND m.order_num = 5
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND q.kind = 'formatif' AND q.module_id = m.id AND q.question IN ('Proyek tim: sistem informasi peminjaman ruang diskusi di perpustakaan kampus. Fitur sudah disepakati dengan kepala layanan, waktunya satu semester, dan tim belum pernah membangun sistem. Paragraf alasan pemilihan model mana yang paling tepat untuk proposal?', 'Proyek tim: sistem informasi peminjaman ruang diskusi di perpustakaan kampus. Fitur sudah disepakati dengan kepala layanan, waktunya satu semester, dan tim belum pernah membangun sistem. Paragraf alasan pemilihan model mana yang paling tepat untuk proposal?') AND q.answer_idx = 3;
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION 'Bab 5 formatif no 19: % baris cocok (harus 1). Tidak ada yang diubah.', k; END IF;
  -- Bab 5 Tes Diagnostik Awal no 8
  UPDATE quiz_questions q SET question = 'Sesudah validasi putaran pertama aplikasi reservasi ruang diskusi perpustakaan, tim menerima tiga masukan: (a) ahli media meminta warna tombol dibuat lebih kontras; (b) ahli materi mencatat aturan durasi peminjaman ruang di halaman bantuan keliru; (c) pengguna melaporkan tombol Simpan Reservasi tidak menyimpan apa pun. Urutan pengerjaan revisi yang paling tepat adalah ...',
         options = '["(a) dan (c) lebih dulu karena keduanya dirasakan langsung oleh pemakai, baru kemudian (b) di halaman bantuan", "(c) lebih dulu karena berasal dari pengguna, baru kemudian (a) dan (b) yang berasal dari ahli media dan ahli materi", "(a) lebih dulu karena paling cepat dikerjakan, baru kemudian (b) dan (c) yang butuh waktu lebih lama", "(b) dan (c) lebih dulu karena menyangkut isi yang salah dan fungsi yang tidak jalan, baru kemudian (a)"]'::JSONB,
         explanation = '[C4] Masukan tentang kesalahan isi dan fungsi yang tidak berjalan didahulukan, baru kemudian soal tampilan. Asal masukan (pengguna atau ahli) dan cepatnya pengerjaan tidak menentukan urutan.'
    FROM courses c JOIN modules m ON m.course_id = c.id AND m.order_num = 5
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND q.kind = 'pre' AND q.course_id = c.id AND q.topik_id = m.id AND q.question IN ('Sesudah validasi putaran pertama aplikasi reservasi ruang diskusi perpustakaan, tim menerima tiga masukan: (a) ahli media meminta warna tombol dibuat lebih kontras; (b) ahli materi mencatat aturan durasi peminjaman ruang di halaman bantuan keliru; (c) pengguna melaporkan tombol Simpan Reservasi tidak menyimpan apa pun. Urutan pengerjaan revisi yang paling tepat adalah ...', 'Sesudah validasi putaran pertama aplikasi reservasi ruang diskusi perpustakaan, tim menerima tiga masukan: (a) ahli media meminta warna tombol dibuat lebih kontras; (b) ahli materi mencatat aturan durasi peminjaman ruang di halaman bantuan keliru; (c) pengguna melaporkan tombol Simpan Reservasi tidak menyimpan apa pun. Urutan pengerjaan revisi yang paling tepat adalah ...') AND q.answer_idx = 3;
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION 'Bab 5 pre no 8: % baris cocok (harus 1). Tidak ada yang diubah.', k; END IF;
  -- Bab 6 Tes Formatif no 2
  UPDATE quiz_questions q SET question = 'Lembar observasi di ruang baca digital sebuah perpustakaan kampus diisi dua pengamat pada hari yang sama, dan hasil keduanya hampir selalu sama. Namun, butir-butirnya mencatat jumlah pengunjung yang masuk, padahal tujuan proyek adalah menilai apakah pemustaka mampu memakai mesin pencari katalog tanpa bantuan petugas. Bagaimana kualitas instrumen ini paling tepat dianalisis?',
         options = '["Instrumen reliabel karena hasil kedua pengamat konsisten, tetapi belum valid karena butirnya tidak mengukur kemampuan yang dituju.", "Instrumen valid sekaligus reliabel, karena kesepakatan dua pengamat yang tinggi sudah membuktikan bahwa butirnya mengukur dengan tepat.", "Instrumen valid tetapi belum reliabel, karena dua pengamat terlalu sedikit untuk memastikan hasil observasi tetap konsisten.", "Instrumen belum valid dan belum reliabel, karena lembar observasi tidak dapat dipakai untuk menilai kemampuan memakai katalog."]'::JSONB,
         explanation = '[C4] Reliabilitas menyangkut konsistensi, sedangkan validitas menyangkut ketepatan sasaran ukur; bab ini menyatakan instrumen yang reliabel belum tentu valid. Pengecoh terkuat menyamakan hasil yang konsisten dengan hasil yang tepat.'
    FROM courses c JOIN modules m ON m.course_id = c.id AND m.order_num = 6
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND q.kind = 'formatif' AND q.module_id = m.id AND q.question IN ('Lembar observasi di ruang baca digital sebuah perpustakaan kampus diisi dua pengamat pada hari yang sama, dan hasil keduanya hampir selalu sama. Namun, butir-butirnya mencatat jumlah pengunjung yang masuk, padahal tujuan proyek adalah menilai apakah pemustaka mampu memakai mesin pencari katalog tanpa bantuan petugas. Bagaimana kualitas instrumen ini paling tepat dianalisis?', 'Lembar observasi di ruang baca digital sebuah perpustakaan kampus diisi dua pengamat pada hari yang sama, dan hasil keduanya hampir selalu sama. Namun, butir-butirnya mencatat jumlah pengunjung yang masuk, padahal tujuan proyek adalah menilai apakah pemustaka mampu memakai mesin pencari katalog tanpa bantuan petugas. Bagaimana kualitas instrumen ini paling tepat dianalisis?') AND q.answer_idx = 0;
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION 'Bab 6 formatif no 2: % baris cocok (harus 1). Tidak ada yang diubah.', k; END IF;
  -- Bab 6 Tes Formatif no 17
  UPDATE quiz_questions q SET question = 'Spesifikasi produk sebuah proposal menyebut: "Aplikasi layanan pesan-antar buku antarfakultas menampilkan status pengantaran buku secara langsung." Mahasiswa diminta menyusun satu baris kisi-kisi angket pengguna yang memuat aspek, indikator, dan contoh butir dari ciri ini. Rancangan mana yang paling baik?',
         options = '["Aspek informasi pengantaran; indikator: pemustaka tahu status pesanan tanpa bertanya ke petugas; butir: \"Saya dapat mengetahui status pengantaran tanpa bertanya ke petugas.\"", "Aspek kepuasan; indikator: pemustaka merasa puas terhadap layanan aplikasi ini pada umumnya; butir: \"Saya puas dengan aplikasi ini dan akan merekomendasikannya kepada teman-teman saya.\"", "Aspek informasi pengantaran; indikator: tampilan status pengantaran menarik bagi pemustaka; butir: \"Tampilan status pengantaran menarik dan informasinya akurat.\"", "Aspek teknologi; indikator: aplikasi memakai teknologi pelacakan pesanan secara langsung; butir: \"Apakah aplikasi ini memakai teknologi pelacakan secara waktu nyata?\""]'::JSONB,
         explanation = '[C6] Rancangan terbaik menurunkan aspek dari ciri produk, indikator yang dapat diamati pengguna, dan butir yang memuat satu hal. Opsi tampilan status menarik memuat dua hal dalam satu butir dan indikatornya tidak sesuai dengan ciri yang dimaksud.'
    FROM courses c JOIN modules m ON m.course_id = c.id AND m.order_num = 6
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND q.kind = 'formatif' AND q.module_id = m.id AND q.question IN ('Spesifikasi produk sebuah proposal menyebut: "Aplikasi layanan pesan-antar buku antarfakultas menampilkan status pengantaran buku secara langsung." Mahasiswa diminta menyusun satu baris kisi-kisi angket pengguna yang memuat aspek, indikator, dan contoh butir dari ciri ini. Rancangan mana yang paling baik?', 'Spesifikasi produk sebuah proposal menyebut: "Aplikasi layanan pesan-antar buku antarfakultas menampilkan status pengantaran buku secara langsung." Mahasiswa diminta menyusun satu baris kisi-kisi angket pengguna yang memuat aspek, indikator, dan contoh butir dari ciri ini. Rancangan mana yang paling baik?') AND q.answer_idx = 0;
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION 'Bab 6 formatif no 17: % baris cocok (harus 1). Tidak ada yang diubah.', k; END IF;
  -- Bab 6 Tes Diagnostik Awal no 10
  UPDATE quiz_questions q SET question = 'Mahasiswa menyusun pedoman wawancara terbuka untuk menggali pengalaman pustakawan memakai repositori institusi. Ia berencana membuktikan mutu pedoman itu dengan menghitung Cronbach''s Alpha. Apa kelemahan rencana ini?',
         options = '["Cronbach''s Alpha memerlukan responden lebih dari 30 orang, sehingga wawancara dengan sedikit pustakawan belum memadai.", "Pedoman wawancara terbuka lebih tepat dinilai dari kredibilitas dan transferabilitas daripada angka statistik.", "Cronbach''s Alpha untuk wawancara dihitung per pertanyaan, sehingga pedoman perlu diubah ke pertanyaan tertutup dulu.", "Cronbach''s Alpha dipakai untuk validitas isi, sehingga reliabilitas pedoman perlu diuji dengan I-CVI."]'::JSONB,
         explanation = '[C4] Bab ini menyebut penilaian mutu instrumen kualitatif seperti pedoman wawancara lebih mengutamakan kredibilitas dan transferabilitas dibanding angka statistik. Cronbach''s Alpha adalah ukuran reliabilitas skor, bukan ukuran validitas isi.'
    FROM courses c JOIN modules m ON m.course_id = c.id AND m.order_num = 6
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND q.kind = 'pre' AND q.course_id = c.id AND q.topik_id = m.id AND q.question IN ('Mahasiswa menyusun pedoman wawancara terbuka untuk menggali pengalaman pustakawan memakai repositori institusi. Ia berencana membuktikan mutu pedoman itu dengan menghitung Cronbach''s Alpha. Apa kelemahan rencana ini?', 'Mahasiswa menyusun pedoman wawancara terbuka untuk menggali pengalaman pustakawan memakai repositori institusi. Ia berencana membuktikan mutu pedoman itu dengan menghitung Cronbach''s Alpha. Apa kelemahan rencana ini?') AND q.answer_idx = 1;
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 1 THEN RAISE EXCEPTION 'Bab 6 pre no 10: % baris cocok (harus 1). Tidak ada yang diubah.', k; END IF;
END $$;
